  1	import { existsSync } from 'node:fs';
  2	import { fileURLToPath } from 'node:url';
  3	import path from 'node:path';
  4	import { durationToWords } from '../lib/words.js';
  5	import { pcmFloatToMp3 } from '../lib/mp3.js';
  6	
  7	const __dirname = path.dirname(fileURLToPath(import.meta.url));
  8	
  9	export const DEFAULT_VOICE = 'M1';
 10	const DEFAULT_STEPS = 8; // denoising steps (upstream Node default); higher = better/slower
 11	const SPEED = 1.0; // neutral — Lectern's player owns the 0.5–3× rate control
 12	const LANG = 'en'; // voice ids don't bind a language; default to English for v1
 13	
 14	// Supertonic ships preset speaker styles M1–M5 / F1–F5 as JSON tensors.
 15	const VOICE_META = {
 16	  M1: { label: 'Male 1', gender: 'Male' },
 17	  M2: { label: 'Male 2', gender: 'Male' },
 18	  M3: { label: 'Male 3', gender: 'Male' },
 19	  M4: { label: 'Male 4', gender: 'Male' },
 20	  M5: { label: 'Male 5', gender: 'Male' },
 21	  F1: { label: 'Female 1', gender: 'Female' },
 22	  F2: { label: 'Female 2', gender: 'Female' },
 23	  F3: { label: 'Female 3', gender: 'Female' },
 24	  F4: { label: 'Female 4', gender: 'Female' },
 25	  F5: { label: 'Female 5', gender: 'Female' },
 26	};
 27	
 28	// Files loadTextToSpeech() needs under <dir>/onnx (see vendored helper.js).
 29	const REQUIRED_ONNX = [
 30	  'duration_predictor.onnx',
 31	  'text_encoder.onnx',
 32	  'vector_estimator.onnx',
 33	  'vocoder.onnx',
 34	  'tts.json',
 35	  'unicode_indexer.json',
 36	];
 37	
 38	// SUPERTONIC_DIR overrides; default is the repo's data/ (matches `npm start` and
 39	// dev desktop). Packaged desktop should set SUPERTONIC_DIR to its userData path.
 40	function baseDir() {
 41	  return process.env.SUPERTONIC_DIR || path.join(__dirname, '..', '..', 'data', 'supertonic');
 42	}
 43	const onnxDir = () => path.join(baseDir(), 'onnx');
 44	const voiceStylePath = (id) => path.join(baseDir(), 'voice_styles', `${id}.json`);
 45	
 46	// On-device: available only once the ~398 MB ONNX assets have been fetched to disk
 47	// (npm run fetch:supertonic), mirroring how ElevenLabs gates on an API key.
 48	export function available() {
 49	  const dir = onnxDir();
 50	  if (!REQUIRED_ONNX.every((f) => existsSync(path.join(dir, f)))) return false;
 51	  return Object.keys(VOICE_META).some((id) => existsSync(voiceStylePath(id)));
 52	}
 53	
 54	// The vendored helper imports onnxruntime-node at module top, so defer loading it
 55	// until first use — the engine must boot fine on machines without the assets/dep.
 56	let helperPromise = null;
 57	const helper = () => (helperPromise ??= import('./supertonic/helper.js'));
 58	
 59	let ttsPromise = null;
 60	async function getTts() {
 61	  if (!ttsPromise) ttsPromise = helper().then((h) => h.loadTextToSpeech(onnxDir()));
 62	  return ttsPromise;
 63	}
 64	
 65	// The voice id is an allowlist against the closed preset set. This MUST gate
 66	// any path built from the id (voiceStylePath(`${id}.json`)) — an unvalidated
 67	// value like '../../../package' would be a path-traversal / file-existence
 68	// oracle. hasOwnProperty (not `id in`) keeps the check prototype-pollution safe.
 69	export function isKnownVoice(id) {
 70	  return Object.prototype.hasOwnProperty.call(VOICE_META, id);
 71	}
 72	
 73	const styleCache = new Map();
 74	async function getStyle(id) {
 75	  if (!isKnownVoice(id)) {
 76	    // Generic message — never echo the (possibly malicious) id back.
 77	    throw Object.assign(new Error('Unknown Supertonic voice'), { status: 400 });
 78	  }
 79	  if (!styleCache.has(id)) {
 80	    if (!existsSync(voiceStylePath(id))) {
 81	      throw Object.assign(new Error('Unknown Supertonic voice'), { status: 400 });
 82	    }
 83	    const h = await helper();
 84	    styleCache.set(id, h.loadVoiceStyle([voiceStylePath(id)]));
 85	  }
 86	  return styleCache.get(id);
 87	}
 88	
 89	export async function synthesize({ text, voice = DEFAULT_VOICE }) {
 90	  const [tts, style] = await Promise.all([getTts(), getStyle(voice)]);
 91	  const { wav, duration } = await tts.call(text, LANG, style, DEFAULT_STEPS, SPEED);
 92	  if (!wav || wav.length === 0) throw new Error('Supertonic produced no audio');
 93	  return {
 94	    audio: pcmFloatToMp3(wav instanceof Float32Array ? wav : Float32Array.from(wav), tts.sampleRate),
 95	    format: 'mp3',
 96	    words: durationToWords(text, duration[0]),
 97	  };
 98	}
 99	
100	export function voices() {
101	  if (!available()) return [];
102	  return Object.entries(VOICE_META)
103	    .filter(([id]) => existsSync(voiceStylePath(id)))
104	    .map(([id, m]) => ({ id, label: `Supertonic ${m.label}`, locale: 'multi', gender: m.gender }));
105	}
106	
107	export function resetForTests() {
108	  helperPromise = null;
109	  ttsPromise = null;
110	  styleCache.clear();
111	}

