 4	
 5	// Each provider declares its own synthesis latency profile. Network providers
 6	// (edge, elevenlabs) return in a few seconds or fail fast, so a tight timeout
 7	// with retry-on-anything is right. Supertonic is on-device ONNX diffusion —
 8	// CPU-bound and much slower, especially for long chunks — so it needs a far
 9	// larger ceiling; and because a timed-out inference is uncancelable and keeps
10	// using CPU, it must never be retried on timeout (a second attempt would race
11	// the abandoned first one and slow both down). `timeoutMs`/`retryOnTimeout` are
12	// consumed by routes/tts.js.
13	export const providers = {
14	  edge: {
15	    synthesize: edge.synthesize,
16	    voices: edge.voices,
17	    isKnownVoice: edge.isKnownVoice,
18	    available: () => true,
19	    timeoutMs: 20_000,
20	    retryOnTimeout: true,
21	  },
22	  elevenlabs: {
23	    synthesize: elevenlabs.synthesize,
24	    voices: elevenlabs.voices,
25	    isKnownVoice: elevenlabs.isKnownVoice,
26	    available: elevenlabs.available,
27	    timeoutMs: 20_000,
28	    retryOnTimeout: true,
29	  },
30	  supertonic: {
31	    synthesize: supertonic.synthesize,
32	    voices: supertonic.voices,
33	    isKnownVoice: supertonic.isKnownVoice,
34	    available: supertonic.available,
35	    timeoutMs: 120_000,
36	    retryOnTimeout: false,
37	  },
38	};
