42	  // 'toString' are all truthy on a plain object and would sail past the guard
43	  // below, turning a bad request into a 5xx plus a stack trace in the log.
44	  const provider = Object.prototype.hasOwnProperty.call(providers, name) ? providers[name] : null;
45	  if (!provider) {
