 1	import * as lame from '@breezystack/lamejs';
 2	
 3	// `@breezystack/lamejs` ships both a namespace and a default export depending on
 4	// the resolver; normalize so `new Mp3Encoder()` works either way.
 5	const Mp3Encoder = lame.Mp3Encoder ?? lame.default?.Mp3Encoder;
 6	
 7	const BLOCK_SIZE = 1152; // one MPEG frame's worth of samples
 8	const KBPS = 128;
 9	
10	// Encode mono Float32 PCM (samples in [-1, 1]) to an mp3 Buffer. Providers whose
11	// native output is WAV/PCM (e.g. Supertonic) use this so every provider can honor
12	// the uniform `format: 'mp3'` contract — clients and the disk cache assume mp3.
13	export function pcmFloatToMp3(samples, sampleRate) {
14	  if (!Mp3Encoder) throw new Error('lamejs Mp3Encoder unavailable');
15	  const encoder = new Mp3Encoder(1, sampleRate, KBPS);
16	
17	  const pcm = new Int16Array(samples.length);
18	  for (let i = 0; i < samples.length; i++) {
19	    const s = Math.max(-1, Math.min(1, samples[i]));
20	    pcm[i] = Math.round(s * 32767);
21	  }
22	
23	  const parts = [];
24	  for (let i = 0; i < pcm.length; i += BLOCK_SIZE) {
25	    const buf = encoder.encodeBuffer(pcm.subarray(i, i + BLOCK_SIZE));
26	    if (buf.length > 0) parts.push(Buffer.from(buf));
27	  }
28	  const tail = encoder.flush();
29	  if (tail.length > 0) parts.push(Buffer.from(tail));
30	
31	  return Buffer.concat(parts);
32	}
 1	const wordSegmenter = new Intl.Segmenter('en', { granularity: 'word' });
 2	
 3	// Edge WordBoundary text arrives without surrounding punctuation, in spoken order.
 4	// A forward-only cursor keeps duplicate words anchored to the right occurrence;
 5	// unmatched words get charStart -1 (client skips their highlight but stays in sync).
 6	export function edgeBoundariesToWords(boundaries, chunkText) {
 7	  const words = [];
 8	  let cursor = 0;
 9	  for (const b of boundaries) {
10	    const idx = b.text ? chunkText.indexOf(b.text, cursor) : -1;
11	    if (idx === -1) {
12	      words.push({ text: b.text, startMs: b.startMs, endMs: b.endMs, charStart: -1, charEnd: -1 });
13	    } else {
14	      words.push({
15	        text: b.text,
16	        startMs: b.startMs,
17	        endMs: b.endMs,
18	        charStart: idx,
19	        charEnd: idx + b.text.length,
20	      });
21	      cursor = idx + b.text.length;
22	    }
23	  }
24	  return words;
25	}
26	
27	// Supertonic (flow-matching) only reports one total clip duration — there is no
28	// token→frame alignment in its graph. We approximate per-word timing with a linear
29	// char→time map over the original chunk text: a word spanning [charStart,charEnd)
30	// gets [charStart/len, charEnd/len] × totalMs. Rougher than real boundaries (speech
31	// rate varies word to word) but monotonic, and char offsets stay exact so highlight
32	// + click-to-jump still anchor correctly. Chunks are ≤300 chars, so drift is bounded.
33	export function durationToWords(text, totalSeconds) {
34	  const len = text.length;
35	  if (!len || !(totalSeconds > 0)) return [];
36	  const totalMs = totalSeconds * 1000;
37	  const words = [];
38	  for (const { segment, index, isWordLike } of wordSegmenter.segment(text)) {
39	    if (!isWordLike) continue;
40	    const charEnd = index + segment.length;
41	    words.push({
42	      text: segment,
43	      startMs: Math.round((index / len) * totalMs),
44	      endMs: Math.round((charEnd / len) * totalMs),
45	      charStart: index,
46	      charEnd,
47	    });
48	  }
49	  return words;
50	}
51	
52	// ElevenLabs `alignment` covers the original input text char-by-char, so segment
53	// indices double as chunk char offsets.
54	export function elevenAlignmentToWords(alignment) {
55	  const text = alignment.characters.join('');
56	  const starts = alignment.characterStartTimesSeconds;
57	  const ends = alignment.characterEndTimesSeconds;
58	  const words = [];
59	  for (const { segment, index, isWordLike } of wordSegmenter.segment(text)) {
60	    if (!isWordLike) continue;
61	    const lastChar = index + segment.length - 1;
62	    if (starts[index] == null || ends[lastChar] == null) continue;
63	    words.push({
64	      text: segment,
65	      startMs: Math.round(starts[index] * 1000),
66	      endMs: Math.round(ends[lastChar] * 1000),
67	      charStart: index,
68	      charEnd: index + segment.length,
69	    });
70	  }
71	  return words;
72	}

