  1	#!/usr/bin/env node
  2	// Downloads the Supertonic-3 ONNX assets + preset voice styles from Hugging Face
  3	// into data/supertonic/ (or $SUPERTONIC_DIR). ~398 MB total; re-runs skip files
  4	// that are already present AND checksum-clean. Pass --force to re-download all.
  5	//
  6	//   npm run fetch:supertonic
  7	//
  8	// These weights are parsed in-process by onnxruntime-node — a native protobuf
  9	// reader — so the download is pinned and verified end to end:
 10	//   * REV is an immutable commit sha. A branch name such as `main` can move
 11	//     under us between the review of a model and the fetch of it, so it is
 12	//     never used here;
 13	//   * every byte is hashed while it streams, and the temp file is promoted to
 14	//     its final name only after its sha256 matches SHA256 below. A mismatched,
 15	//     truncated or interrupted transfer is unlinked, so a half-written file can
 16	//     never be mistaken for a present one on the next run;
 17	//   * files already on disk are re-hashed before being skipped, which also
 18	//     re-validates anything an older, unchecksummed version of this script left
 19	//     behind.
 20	//
 21	// Model weights are OpenRAIL-M licensed (see the repo); this only fetches them.
 22	//
 23	// ─── Bumping the model (how SHA256 below was generated) ──────────────────────
 24	// 1. Read the new head commit sha and put it in REV:
 25	//      curl -s https://huggingface.co/api/models/Supertone/supertonic-3 | jq -r .sha
 26	// 2. The four large .onnx files are Git-LFS, and LFS pointers carry the sha256
 27	//    as their oid — so the tree API hands them over without downloading 398 MB:
 28	//      REV=<sha from step 1>
 29	//      for d in onnx voice_styles; do
 30	//        curl -s "https://huggingface.co/api/models/Supertone/supertonic-3/tree/$REV/$d?recursive=true"
 31	//      done | jq -r '.[] | select(.lfs) | "\(.path) \(.lfs.oid)"'
 32	// 3. The small JSON files are plain git blobs (no .lfs field, a few hundred KB
 33	//    each) — fetch and hash them directly:
 34	//      curl -sL "https://huggingface.co/Supertone/supertonic-3/resolve/$REV/<path>" | shasum -a 256
 35	//    Cross-check each one against the tree API's git blob `oid` with
 36	//    `git hash-object <file>` before trusting it.
 37	// ─────────────────────────────────────────────────────────────────────────────
 38	import { createHash } from 'node:crypto';
 39	import { mkdir, rename, stat, unlink } from 'node:fs/promises';
 40	import { createReadStream, createWriteStream } from 'node:fs';
 41	import { Readable } from 'node:stream';
 42	import { pipeline } from 'node:stream/promises';
 43	import { fileURLToPath } from 'node:url';
 44	import path from 'node:path';
 45	
 46	const REPO = 'Supertone/supertonic-3';
 47	// Immutable commit sha — verified as the head of `main` on 2026-09-05 via
 48	// https://huggingface.co/api/models/Supertone/supertonic-3 (.sha).
 49	const REV = '3cadd1ee6394adea1bd021217a0e650ede09a323';
 50	const BASE = `https://huggingface.co/${REPO}/resolve/${REV}`;
 51	
 52	const ONNX = ['duration_predictor.onnx', 'text_encoder.onnx', 'vector_estimator.onnx', 'vocoder.onnx', 'tts.json', 'unicode_indexer.json'];
 53	const STYLES = ['M1', 'M2', 'M3', 'M4', 'M5', 'F1', 'F2', 'F3', 'F4', 'F5'].map((v) => `${v}.json`);
 54	const FILES = [...ONNX.map((f) => `onnx/${f}`), ...STYLES.map((f) => `voice_styles/${f}`)];
 55	
 56	// sha256 of every file in FILES, at REV. Regenerate with the recipe above.
 57	const SHA256 = {
 58	  'onnx/duration_predictor.onnx': 'c3eb91414d5ff8a7a239b7fe9e34e7e2bf8a8140d8375ffb14718b1c639325db',
 59	  'onnx/text_encoder.onnx': 'c7befd5ea8c3119769e8a6c1486c4edc6a3bc8365c67621c881bbb774b9902ff',
 60	  'onnx/vector_estimator.onnx': '883ac868ea0275ef0e991524dc64f16b3c0376efd7c320af6b53f5b780d7c61c',
 61	  'onnx/vocoder.onnx': '085de76dd8e8d5836d6ca66826601f615939218f90e519f70ee8a36ed2a4c4ba',
 62	  'onnx/tts.json': '42078d3aef1cd43ab43021f3c54f47d2d75ceb4e75f627f118890128b06a0d09',
 63	  'onnx/unicode_indexer.json': '9bf7346e43883a81f8645c81224f786d43c5b57f3641f6e7671a7d6c493cb24f',
 64	  'voice_styles/M1.json': 'e35604687f5d23694b8e91593a93eec0e4eca6c0b02bb8ed69139ab2ea6b0a5b',
 65	  'voice_styles/M2.json': 'b76cbf62bac707c710cf0ae5aba5e31eea1a6339a9734bfae33ab98499534a50',
 66	  'voice_styles/M3.json': 'ea1ac35ccb91b0d7ecad533a2fbd0eec10c91513d8951e3b25fbba99954e159b',
 67	  'voice_styles/M4.json': 'ca8eefad4fcd989c9379032ff3e50738adc547eeb5e221b82593a6d7b3bac303',
 68	  'voice_styles/M5.json': 'dd22b92740314321f8ae11c5e87f8dd60d060f15dd3a632b5adf77f471f77af2',
 69	  'voice_styles/F1.json': 'bbdec6ee00231c2c742ad05483df5334cab3b52fda3ba38e6a07059c4563dbc2',
 70	  'voice_styles/F2.json': '7c722c6a72707b1a77f035d67f0d1351ba187738e06f7683e8c72b1df3477fc6',
 71	  'voice_styles/F3.json': '12f6ef2573baa2defa1128069cb59f203e3ab67c92af77b42df8a0e3a2f7c6ab',
 72	  'voice_styles/F4.json': 'c2fa764c1225a76dfc3e2c73e8aa4f70d9ee48793860eb34c295fff01c2e032b',
 73	  'voice_styles/F5.json': '45966e73316415626cf41a7d1c6f3b4c70dbc1ba2bee5c1978ef0ce33244fc8d',
 74	};
 75	
 76	// A file added to FILES without a pinned digest would download unverified.
 77	// Fail the whole run at startup, before a single byte moves.
 78	const unpinned = FILES.filter((rel) => !SHA256[rel]);
 79	if (unpinned.length) throw new Error(`fetch-supertonic: no sha256 pinned for ${unpinned.join(', ')}`);
 80	
 81	const __dirname = path.dirname(fileURLToPath(import.meta.url));
 82	const destDir = process.env.SUPERTONIC_DIR || path.join(__dirname, '..', 'data', 'supertonic');
 83	const force = process.argv.includes('--force');
 84	
 85	const mb = (n) => `${(n / 1e6).toFixed(1)} MB`;
