 87	async function exists(p) {
 88	  try {
 89	    return (await stat(p)).size > 0;
 90	  } catch {
 91	    return false;
 92	  }
 93	}
 94	
 95	async function sha256File(p) {
 96	  const hash = createHash('sha256');
 97	  for await (const chunk of createReadStream(p)) hash.update(chunk);
 98	  return hash.digest('hex');
 99	}
