101	// Streams rel to <out>.tmp while hashing it, and renames into place ONLY after
102	// the digest matches. Any failure unlinks the tmp file, so the final path never
103	// holds unverified bytes.
104	async function download(rel, out, want) {
105	  const url = `${BASE}/${rel}?download=true`;
106	  const res = await fetch(url);
107	  if (!res.ok || !res.body) throw new Error(`${rel}: HTTP ${res.status}`);
108	  const total = Number(res.headers.get('content-length')) || 0;
109	  process.stdout.write(`  ↓ ${rel}${total ? ` (${mb(total)})` : ''} … `);
110	  const tmp = `${out}.tmp`;
111	  const hash = createHash('sha256');
112	  try {
113	    await pipeline(
114	      Readable.fromWeb(res.body),
115	      async function* (source) {
116	        for await (const chunk of source) {
117	          hash.update(chunk);
118	          yield chunk;
119	        }
120	      },
121	      createWriteStream(tmp),
122	    );
123	    const got = hash.digest('hex');
124	    if (got !== want) throw new Error(`${rel}: sha256 mismatch\n    expected ${want}\n    got      ${got}`);
125	    await rename(tmp, out);
126	  } catch (err) {
127	    await unlink(tmp).catch(() => {});
128	    console.log('FAILED');
129	    throw err;
130	  }
131	  console.log('done (sha256 verified)');
132	}
