134	async function ensure(rel) {
135	  const out = path.join(destDir, rel);
136	  const want = SHA256[rel];
137	  await mkdir(path.dirname(out), { recursive: true });
138	  if (!force && (await exists(out))) {
139	    if ((await sha256File(out)) === want) {
140	      console.log(`  ✓ ${rel} (already present, sha256 verified)`);
141	      return;
142	    }
143	    console.log(`  ! ${rel} on disk does not match ${REV} — re-downloading`);
144	  }
