 61	      { type: 'audio', data: Buffer.from('abc') },
 62	      { type: 'WordBoundary', offset: 1_000_000, duration: 2_000_000, text: 'Hello' },
 63	      { type: 'audio', data: Buffer.from('def') },
 64	      { type: 'WordBoundary', offset: 4_000_000, duration: 1_000_000, text: 'world' },
