 1	import { Router } from 'express';
 2	import { getProvider } from '../providers/index.js';
 3	import { cacheKey } from '../lib/cache.js';
 4	import { createSemaphore, withTimeout, retryOnce } from '../lib/semaphore.js';
 5	
 6	const MAX_TTS_CHARS = 2000;
 7	// Fallback when a provider doesn't declare its own; real timeouts live in
 8	// providers/index.js because they're provider-specific (network vs on-device).
 9	const DEFAULT_TIMEOUT_MS = 20_000;
10	
11	export function ttsRouter({ cache }) {
12	  const router = Router();
13	  const semaphore = createSemaphore(2);
14	
15	  router.post('/', async (req, res, next) => {
16	    const { provider: providerName = 'edge', voice, text } = req.body ?? {};
17	    try {
18	      if (!text || typeof text !== 'string' || !text.trim()) {
19	        return res.status(400).json({ error: 'text is required' });
20	      }
21	      if (text.length > MAX_TTS_CHARS) {
22	        return res.status(400).json({ error: `text exceeds ${MAX_TTS_CHARS} characters` });
23	      }
24	      if (!voice || typeof voice !== 'string') {
25	        return res.status(400).json({ error: 'voice is required' });
26	      }
27	      const provider = getProvider(providerName);
28	      if (!provider.available()) {
29	        return res
30	          .status(400)
31	          .json({ error: `Provider "${providerName}" is not configured (missing API key)` });
32	      }
33	      // Every provider builds a request from this id — SSML for edge, a file
34	      // path for supertonic — so it must be one the provider publishes, never
35	      // a caller-supplied string. Never echo the id back in the error.
36	      if (!(await provider.isKnownVoice(voice))) {
37	        return res.status(400).json({ error: `Unknown voice for provider "${providerName}"` });
38	      }
39	
40	      const key = cacheKey(providerName, voice, text);
41	      const cached = await cache.get(key);
42	      if (cached) {
43	        return res.json({
44	          audioBase64: cached.audio.toString('base64'),
45	          format: cached.format,
46	          words: cached.words,
47	          cached: true,
48	        });
49	      }
50	
51	      const timeoutMs = provider.timeoutMs ?? DEFAULT_TIMEOUT_MS;
52	      const retryOnTimeout = provider.retryOnTimeout ?? true;
53	      const result = await semaphore.run(() =>
54	        retryOnce(
55	          () => withTimeout(provider.synthesize({ text, voice }), timeoutMs, 'TTS synthesis'),
56	          { shouldRetry: (err) => retryOnTimeout || !err.timeout },
57	        ),
58	      );
59	      await cache.put(key, result);
60	      res.json({
61	        audioBase64: result.audio.toString('base64'),
62	        format: result.format,
63	        words: result.words,
64	        cached: false,
65	      });
66	    } catch (err) {
67	      err.status ??= 503;
68	      err.message = `TTS failed (${providerName}): ${err.message}`;
69	      next(err);
70	    }
71	  });
72	
73	  return router;
74	}
 1	// Structural caps and normalization for content that reaches the store or the
 2	// synchronous segmenter. The global 5 MB JSON body cap bounds raw bytes but not
 3	// block COUNT or per-block length, so a within-5MB payload could still stall the
 4	// single event loop in segmentDocument()'s nested loops + Intl.Segmenter — and a
 5	// compressed PDF or a fetched page expands server-side, past any body cap at
 6	// all. These limits sit far above any real article, so they reject abuse without
 7	// ever tripping on legitimate documents.
 8	export const MAX_BLOCKS = 5000;
 9	export const MAX_BLOCK_CHARS = 50_000;
10	export const MAX_TOTAL_CHARS = 2_000_000;
11	
12	// Returns an error message if the blocks array exceeds structural limits, else
13	// null. Tolerant of non-string/absent text (other validators reject those).
14	export function blocksOverLimit(blocks) {
15	  if (blocks.length > MAX_BLOCKS) return `too many blocks (max ${MAX_BLOCKS})`;
16	  let total = 0;
17	  for (const b of blocks) {
18	    const len = typeof b?.text === 'string' ? b.text.length : 0;
19	    if (len > MAX_BLOCK_CHARS) return `a block exceeds ${MAX_BLOCK_CHARS} characters`;
20	    total += len;
21	    if (total > MAX_TOTAL_CHARS) return `document exceeds ${MAX_TOTAL_CHARS} characters`;
22	  }
23	  return null;
24	}
25	
26	// Returns an error message if a single text string is too large, else null.
27	export function textOverLimit(text) {
28	  return text.length > MAX_TOTAL_CHARS ? `text exceeds ${MAX_TOTAL_CHARS} characters` : null;
29	}
30	
31	// Titles are caller-controlled on every import path: a page's <title> via the
32	// extension, Readability's title from any site, a multipart filename. They land
33	// in the library meta and are rendered by all three frontends. Truncation beats
34	// rejection here — an over-long title is never a reason to lose the import.
35	export const MAX_TITLE_CHARS = 300;
36	
37	// The closed set of source kinds the clients render. public/js/main.js maps
38	// source.type through an object literal, so an unrecognized value silently falls
39	// through to a generic label; /import/blocks takes this straight from a live
40	// page, so it is normalized rather than trusted.
41	const SOURCE_TYPES = new Set(['url', 'pdf', 'text']);
42	
43	// Trims and truncates a title to MAX_TITLE_CHARS. Non-strings pass through
