554	
555	          // Decades: 70s, 1970s -> SEVENTIES, NINETEEN SEVENTIES  
556	          part.text = part.text.replace(/\b(\d{2,4})[''']?\s?[sS](?=\s|[.,!?;:]|$)/g, (match, decade) => {
557	            const result = this.convertDecade(decade);
