638	  * Convert graphemes to phonemes.
639	  *
640	  * @param {string} s Word, normalized and in upper case
641	  * @return {string[]} Array of phonemes
642	  */
643	  phonemizeWord(s) {
644	
645	    const phonemes = [];
646	
647	    // Dictionary lookup
648	    if ( this.dictionary ) {
649	      if ( this.dictionary.hasOwnProperty(s) ) {
650	        if ( this.settings.trace ) {
651	          utils.trace( 'Dictionary match: "' + s + '" => "' + this.dictionary[s].join("") + '"' );
652	        }
653	        phonemes.push( ...this.dictionary[s] );
654	        s = "";
655	      } else if ( s.length >= 5 ) {
656	        const len = s.length;
657	        for(let i=1; i<3; i++) {
658	          const part = s.substring(0,len-i);
659	          if ( this.dictionary.hasOwnProperty(part) ) {
660	            if ( this.settings.trace ) {
661	              utils.trace( 'Dictionary partial: "' + part + '" => "' + this.dictionary[part].join("") + '"' );
662	            }
663	            phonemes.push( ...this.dictionary[part] );
664	            s = s.substring(len-i);
665	            break;
666	          }
667	        }
668	      }
669	    }
670	
671	    // If still not resolved, use rules
672	    if ( s.length ) {
673	      const firstPhoneme = phonemes.length;
674	      const chars = [...s];
675	      let len = chars.length;
676	      let i = 0;
677	      while( i < len ) {
678	        const c = chars[i];
679	        if ( this.punctuations.hasOwnProperty(c) ) {
680	          phonemes.push( this.punctuations[c] );
681	          i++;
682	        } else {
683	          const ruleset = this.rules[c];
684	          if ( ruleset ) {
685	            for(let j=0; j<ruleset.length; j++) {
686	              const rule = ruleset[j];
687	              const test = s.substring(0, i) + c.toLowerCase() + s.substring(i+1);
688	              let matches = test.match(rule.regex);
689	              if ( matches ) {
690	                rule.phonemes.forEach( ph =>  {
691	                  phonemes.push( ph );
692	                });
693	                i += rule.move;
694	                break;
695	              }
696	            }
697	          } else {
698	            i++;
699	          }
700	        }
701	      }
702	      if ( this.settings.trace ) {
703	        utils.trace( 'Rules: "' + s + '" => "' + phonemes.slice(firstPhoneme).join("") + '"' );
704	      }
705	    }
706	
707	    return phonemes;
708	  }
