 72	export class Deferred {
 73	  constructor() {
 74	    this.status = "pending";
 75	    this.promise = new Promise((resolve, reject) => {
 76	      this.resolve = (value) => {
 77	        this.status = "resolved";
 78	        resolve(value);
 79	      };
 80	      this.reject = (reason) => {
 81	        this.status = "rejected";
 82	        reject(reason);
 83	      };
 84	    });
 85	  }
 86	}
 87	
 88	// Create a lookup table for base64 decoding
 89	const b64Chars = 'REDACTED/';
 90	const b64Lookup = typeof Uint8Array === 'undefined' ? [] : new Uint8Array(256);
 91	for (let i = 0; i < b64Chars.length; i++) b64Lookup[b64Chars.charCodeAt(i)] = i;
 92	
 93	/**
 94	* Convert a Base64 MP3 chunk to ArrayBuffer.
 95	* @param {string} chunk Base64 encoded chunk
 96	* @return {ArrayBuffer} ArrayBuffer
 97	*/
 98	export function b64ToArrayBuffer(chunk) {
 99	
100	  // Calculate the needed total buffer length
101	  let bufLen = 3 * chunk.length / 4;
102	  if (chunk[chunk.length - 1] === '=') {
103	    bufLen--;
104	    if (chunk[chunk.length - 2] === '=') {
105	      bufLen--;
106	    }
107	  }
108	
109	  // Create the ArrayBuffer
110	  const arrBuf = new ArrayBuffer(bufLen);
111	  const arr = new Uint8Array(arrBuf);
112	  let i, p = 0, c1, c2, c3, c4;
113	
114	  // Populate the buffer
115	  for (i = 0; i < chunk.length; i += 4) {
116	    c1 = b64Lookup[chunk.charCodeAt(i)];
117	    c2 = b64Lookup[chunk.charCodeAt(i+1)];
118	    c3 = b64Lookup[chunk.charCodeAt(i+2)];
119	    c4 = b64Lookup[chunk.charCodeAt(i+3)];
120	    arr[p++] = (c1 << 2) | (c2 >> 4);
121	    arr[p++] = ((c2 & 15) << 4) | (c3 >> 2);
122	    arr[p++] = ((c3 & 3) << 6) | (c4 & 63);
123	  }
124	
125	  return arrBuf;
126	}
