128	
129	/**
130	* Encode float32 samples to PCM 16bit LE buffer.
131	*
132	* @param {Float32Array} samples Float32 samples
133	* @param {number} sampleRate Sample rate
134	* @param {boolean} [header=true] If true, add WAV header
135	* @return {ArrayBuffer} WAV or raw PCM 16bit LE samples.
136	*/
137	export function encodeAudio(samples, sampleRate, header=true) {
138	  const len = samples.length;
139	  let offset = header ? 44 : 0;
140	  const buffer = new ArrayBuffer(offset + len * 2);
141	  const view = new DataView(buffer);
142	
143	  // Write WAV header
144	  if ( header ) {
145	
146	    function writeString(view, off, string) {
147	      for (let i = 0; i < string.length; i++) {
148	        view.setUint8(off + i, string.charCodeAt(i));
149	      }
150	    }
151	
152	    writeString(view, 0, "RIFF");
153	    view.setUint32(4, 32 + samples.length * 2, true);
154	    writeString(view, 8, "WAVE");
155	    writeString(view, 12, "fmt ");
156	    view.setUint32(16, 16, true);
157	    view.setUint16(20, 1, true);
158	    view.setUint16(22, 1, true);
159	    view.setUint32(24, sampleRate, true);
160	    view.setUint32(28, sampleRate * 2, true);
161	    view.setUint16(32, 2, true);
162	    view.setUint16(34, 16, true);
163	    writeString(view, 36, "data");
164	    view.setUint32(40, samples.length * 2, true);
165	  }
166	
167	  // Write samples as PCM 16bit LE
168	  for (let i = 0; i < len; i++, offset += 2) {
169	    const s = Math.max(-1, Math.min(1, samples[i]));
170	    view.setInt16(offset, s < 0 ? s * 0x8000 : s * 0x7fff, true);
171	  }
172	
173	  return buffer;
174	}
175	
176	/**
177	* Concatenate an array of ArrayBuffers.
178	* @param {ArrayBuffer[]} bufs Array of ArrayBuffers
179	* @return {ArrayBuffer} Concatenated ArrayBuffer
180	*/
181	export function concatArrayBuffers(bufs) {
182	  const len = bufs.length;
183	  if ( len === 1 ) return bufs[0];
184	  let byteLen = 0;
185	  for( let i=0; i<len; i++ ) {
186	    byteLen += bufs[i].byteLength;
187	  }
188	  const buf = new ArrayBuffer(byteLen);
189	  const arr = new Uint8Array(buf);
190	  let p = 0;
191	  for( let i=0; i<len; i++ ) {
192	    arr.set( new Uint8Array(bufs[i]), p);
193	    p += bufs[i].byteLength;
194	  }
195	  return buf;
196	}
197	
198	/**
199	* Convert PCM buffer to AudioBuffer.
200	* NOTE: Only signed 16bit little endian supported.
201	*
202	* @param {ArrayBuffer} buf PCM 16bit LE array buffer
203	* @return {AudioBuffer} AudioBuffer
204	*/
205	export function pcmToAudioBuffer(buf,samplerate,ctx) {
206	  const arr = new Int16Array(buf);
207	  const floats = new Float32Array(arr.length);
208	  const len = arr.length;
209	  for( let i=0; i<len; i++ ) {
210	    floats[i] = (arr[i] >= 0x8000) ? -(0x10000 - arr[i]) / 0x8000 : arr[i] / 0x7FFF;
211	  }
212	  const audio = ctx.createBuffer(1, floats.length, samplerate );
213	  audio.copyToChannel( floats, 0 , 0 );
214	  return audio;
215	}
216	
217	/**
218	 * Inserts new segments of silence into a Float32Array of audio samples.
219	 *
220	 * @param {Float32Array} samples The original audio samples
221	 * @param {number} sampleRate The sample rate of the audio in Hz (e.g., 44100)
222	 * @param {number[][]} silences Sorted array of [time, duration] in milliseconds
223	 * @returns {Float32Array} A new Float32Array with silence segments inserted.
224	 */
225	export function insertSilences(samples, samplerate, silences) {
226	  
227	  // Convert times and durations to number of samples
228	  let nNewSamples = 0; // Total new samples
229	  silences.forEach( x => {
230	    x[0] = Math.floor((x[0] / 1000) * samplerate);
231	    x[1] = Math.floor((x[1] / 1000) * samplerate);
232	    nNewSamples += x[1];
233	  });
234	
235	  // New Float32Array
236	  const result = new Float32Array( samples.length + nNewSamples );
237	
238	  // Copy existing samples
239	  let readPos = 0;
240	  let writePos = 0;
241	  silences.forEach( x => {
242	    const start = Math.min(x[0], samples.length);
243	    const len = start - readPos;
244	    if (len > 0) {
245	      result.set(samples.subarray(readPos, start), writePos);
246	      readPos += len;
247	      writePos += len;
248	    }
249	    writePos += x[1]; // Add silence
250	  });
251	  if (readPos < samples.length) {
252	    result.set(samples.subarray(readPos), writePos);
253	  }
254	
255	  return result;
256	}
