  1	import * as utils from "./utils.mjs";
  2	
  3	// Dynamic imports
  4	let StyleTextToSpeech2Model;
  5	let AutoTokenizer;
  6	let Tensor;
  7	let env;
  8	let LogLevel;
  9	
 10	// Status flags
 11	let filesProgress;
 12	let isReady = false;
 13	let isProcessing = false;
 14	let isTraceConnection = false;
 15	let isTraceG2P = false;
 16	let isTraceLanguage = false;
 17	
 18	// Other globals
 19	let model = null; // Model
 20	let tokenizer = null; // Tokenizer
 21	const languages = new Map(); // Language modules
 22	const voices = new Map(); // Voices
 23	let settings = {}; // Settings
 24	const queue = []; // Text-to-speech work queue
 25	
 26	// Different event handler for Node.js and browsers
 27	let eventHandler;
 28	let fileReader;
 29	const isNode = typeof import.meta !== 'undefined' &&
 30	         typeof import.meta.url === 'string' &&
 31	         import.meta.url.startsWith('file://');
 32	if (isNode) {
 33	  const { readFile } = await import ('node:fs/promises');
 34	  fileReader = readFile;
 35	  const { parentPort } = await import('node:worker_threads');
 36	  eventHandler = parentPort;
 37	} else {
 38	  eventHandler = self;
 39	}
 40	
 41	/**
 42	* Event handler.
 43	*
 44	* @param {MessageEvent} ev Message event
 45	*/
 46	eventHandler.onmessage = async (ev) => {
 47	  const message = ev.data;
 48	  if ( message.type === 'synthesize' ) {
 49	    queue.push(message);
 50	    process();
 51	  } else if ( message.type === 'setup' ) {
 52	    const o = message.data;
 53	    if ( typeof o === 'object' && !Array.isArray(o) && o !== null ) {
 54	      Object.assign(settings, o);
 55	    }
 56	  } else if ( message.type === 'connect' ) {
 57	    const o = message.data;
 58	    if ( typeof o === 'object' && !Array.isArray(o) && o !== null ) {
 59	      Object.assign(settings, o);
 60	      isTraceConnection = settings.trace & utils.traceMask.connection;
 61	      isTraceG2P = settings.trace & utils.traceMask.g2p;
 62	      isTraceLanguage = settings.trace & utils.traceMask.language;
 63	    }
 64	    connect();
 65	  } else {
 66	    console.error('HeadTTS Worker: Unknown message type "' + message.type + '".');
 67	  }
 68	}
 69	
 70	/**
 71	* Calculate and report progress
 72	*
 73	* @param {ProgressEvent} ev Progress event
 74	*/
 75	function progress(ev) {
 76	
 77	  // Update data
 78	  if ( ev.status === 'progress' ) {
 79	    if ( !filesProgress.hasOwnProperty(ev.file) ) {
 80	      filesProgress[ev.file] = { loaded: 0, total: 0 };
 81	    }
 82	    filesProgress[ev.file].loaded = ev.loaded;
 83	    filesProgress[ev.file].total = ev.total;
 84	
 85	    // Calculate progress
 86	    let loaded = 0;
 87	    let total = 0;
 88	    for( let key in filesProgress ) {
 89	      loaded += filesProgress[key].loaded;
 90	      total += filesProgress[key].total;
 91	    }
 92	
 93	    // Update progress
 94	    eventHandler.postMessage({
 95	      type: "progress",
 96	      data: {
 97	        loaded: loaded,
 98	        total: total,
 99	        lengthComputable: ( total && (total > 0) && (total >= loaded) )
100	      }
101	    });
102	
103	  }
104	
105	}
106	
107	/**
108	* Set up the model and pre-load voices.
109	*/
110	async function connect() {
111	
112	  if ( isTraceConnection ) {
113	    utils.trace( 'Loading model "' + settings.transformersModule + '" started.' );
114	  }
115	
116	  // Load modules dynamically
117	  try {
118	    ({ StyleTextToSpeech2Model, AutoTokenizer, Tensor, env, LogLevel } = await import(settings.transformersModule));
119	    
120	    // Set log level to ERROR
121	    env.logLevel = LogLevel.ERROR;
122	
123	  } catch(error) {
124	    console.error("HeadTTS Worker: Importing modules failed, error=", error);
125	    throw new Error("Importing modules failed.");
126	  }
127	
128	  if ( isTraceConnection ) {
129	    utils.trace( 'Loading model "' + settings.transformersModule + '" ended.' );
130	  }
131	
132	  try {
133	
134	    // Clear progress data
135	    filesProgress = {};
136	
137	    let voices = settings.voices || [];
138	    const results = await Promise.all([
139	      StyleTextToSpeech2Model.from_pretrained( settings.model, {
140	        dtype: settings.dtype,
141	        device: settings.device,
142	        progress_callback: progress
143	      }),
144	      AutoTokenizer.from_pretrained( settings.model, {
145	        progress_callback: progress
146	      }),
147	      ...settings.voices.map( async (x) => {
148	        try {
149	          loadVoice(x);
150	        } catch(error) {
151	          // Ignore errors on pre-load
152	        }
153	      }),
154	      ...settings.languages.map( async (x) => {
155	        try {
156	          loadLanguage(x);
157	        } catch(error) {
158	          // Ignore errors on pre-load
159	        }
160	      })
161	    ]);
162	    model = results[0];
163	    tokenizer = results[1];
164	  } catch(error) {
165	    console.error("HeadTTS Worker: Loading models failed, error=", error, " settings=", settings);
166	    throw new Error("Loading models failed.");
167	  }
168	
169	  // Ready
170	  isReady = true;
171	  eventHandler.postMessage({ type: "ready" });
172	
173	  // Process
174	  process();
175	}
176	
177	/**
178	* Load a specific language module.
179	*
180	* @param {string} lang Language, e.g. "en-us"
181	* @return {Object} Language module instance.
182	*/
183	async function loadLanguage(lang) {
184	  if ( languages.has(lang) ) {
185	    return languages.get(lang);
186	  } else {
187	    if ( isTraceConnection ) {
188	      utils.trace( 'Importing language "' + lang + '".' );
189	    }
190	    let Language;
191	    ({ Language } = await import("./language-" + lang.toLowerCase() + ".mjs"));
192	    const language = new Language({
193	      trace: isTraceLanguage
194	    });
195	    if ( isNode && settings.dictionaryPath ) {
196	      if ( !settings.dictionaryPath.endsWith("/") ) {
197	        settings.dictionaryPath += "/";
198	      }
199	      await language.loadDictionary( settings.dictionaryPath + lang.toLowerCase() + ".txt");
200	    } else if ( !isNode && settings.dictionaryURL ) {
201	      if ( !settings.dictionaryURL.endsWith("/") ) {
202	        settings.dictionaryURL += "/";
203	      }
204	      await language.loadDictionary( settings.dictionaryURL + lang.toLowerCase() + ".txt");
205	    }
206	    languages.set( lang, language );
207	    return language;
208	  }
209	}
210	
211	/**
212	* Load a specific voice.
213	*
214	* @param {string} s Voice name.
215	* @return {ArrayBuffer} Voice data.
216	*/
217	async function loadVoice(s) {
