254	/**
255	* Calculate starting times and durations for TalkingHead words and visemes.
256	*
257	* @param {Object} o TalkingHead audio object to be updated
258	* @param {number[]} ds Token durations in frames
259	* @param {number[][]} silences Sorted array of [index,duration] of silences.
260	*/
261	function updateTimestamps(o,ds,silences) {
262	
263	  // Calculate starting times in milliseconds
264	  const scaler = 1000 / settings.frameRate; // From frames to milliseconds
265	  const times = [];
266	  let t = 0;
267	  let len = ds.length;
268	  for( let i=0; i<len; i++ ) {
269	    times.push( Math.round(t) );
270	    t += scaler * ds[i];
271	  }
272	  times.push( Math.round(t) ); // Last entry
273	
274	  // Shift times based on silent periods and
275	  // convert phoneme indexes to original starting times
276	  const shifts = silences.map( x => [x[0]+1,x[1]] );
277	  silences.forEach( x => x[0] = times[x[0]] - 20 );
278	  shifts.forEach( x => {
279	    for( let i=x[0]; i<times.length; i++ ) {
280	      times[i] += x[1];
281	    }
282	  });
283	
284	  // Calculate word times and durations (+1 because of $)
285	  len = o.words.length;
286	  for( let i=0; i<len; i++ ) {
287	    const start = times[o.wtimes[i]+1] + settings.deltaStart;
288	    const end = times[o.wdurations[i]+1] + settings.deltaEnd;
289	    const duration = end - start;
290	    o.wtimes[i] = start;
291	    o.wdurations[i] = duration;
292	  }
293	
294	  // Calculate visemes times and durations (+1 because of $)
295	  len = o.visemes.length;
296	  for( let i=0; i<len; i++ ) {
297	    const start = times[o.vtimes[i]+1] + settings.deltaStart;
298	    const end = times[o.vdurations[i]+1] + settings.deltaEnd;
299	    const duration = end - start;
300	    o.vtimes[i] = start;
301	    o.vdurations[i] = duration;
302	  }
303	
304	}
