307	/**
308	* Process the work queue: phonemize the text, tokenize phonemes, load voice,
309	* run inference, encode audio, and post the response message.
310	*/
311	async function process() {
312	  if ( isProcessing || !isReady ) return;
313	  isProcessing = true;
314	  while( queue.length ) {
315	    const item = queue[0];
316	    queue.shift();
317	    const d = item.data;
318	
319	    // Generate tokens/phonemes and initialize TalkingHead audio object
320	    let language;
321	    try {
322	      language = await loadLanguage(d.language);
323	    } catch(error) {
324	      console.error("HeadTTS Worker: Error loading language module, error=", error, " item=", item);
325	      item.ref = item.id;
326	      delete item.id;
327	      item.type = "error";
328	      item.data = { error: "Error loading language module '" + d.language + "'." };
329	      eventHandler.postMessage(item);
330	      continue;
331	    }
332	    const { phonemes, metadata, silences } = language.generate(d.input);
333	    if ( isTraceG2P ) {
334	      if ( typeof d.input === "string" ) {
335	        utils.trace( "G2P: " + d.input );
336	      } else if ( Array.isArray(d.input) ) {
337	        d.input.forEach( x => {
338	          if ( typeof x === "string" ) {
339	            utils.trace( "G2P: " + x );
340	          } else {
341	            utils.trace( "G2P: { type=" + x.type + ", value=" + x.value + " }" );
342	          }
343	        });
344	      }
345	      utils.trace( "G2P: => " + phonemes.join("") + ", metadata=", metadata );
346	    }
347	
348	    // Generate input IDs and run the model
349	    const { input_ids } = tokenizer(phonemes.join(""), {
350	      truncation: true
351	    });
352	    const num_tokens = Math.min(Math.max(input_ids.size - 2, 0), 509);
353	    let voice;
354	    try {
355	      voice = await loadVoice(d.voice);
356	    } catch(error) {
357	      console.error("HeadTTS Worker: Error loading voice, error=", error, " item=", item);
358	      item.ref = item.id;
359	      delete item.id;
360	      item.type = "error";
361	      item.data = { error: "Error loading voice '" + d.voice + "'." };
362	      eventHandler.postMessage(item);
363	      continue;
364	    }
365	    const data = new Float32Array(voice);
366	    const offset = num_tokens * settings.styleDim;
367	    const voiceData = data.slice(offset, offset + settings.styleDim);
368	    const inputs = {
369	      input_ids,
370	      style: new Tensor("float32", voiceData, [1, settings.styleDim]),
371	      speed: new Tensor("float32", [d.speed], [1]),
372	    };
373	    const { waveform, durations } = await model(inputs);
374	
375	    // Generate timestamps from durations
376	    const durationsFrames = Array.from(durations.data);
377	    updateTimestamps( metadata, durationsFrames, silences );
378	
379	    // Encode audio
380	    const samplerate = settings.audioSampleRate;
381	    let samples = waveform.data;
382	    if ( silences.length ) {
383	      samples = utils.insertSilences(samples, samplerate, silences)
384	    }
385	    if ( d.audioEncoding === "pcm" ) {
386	      metadata.audio = utils.encodeAudio(samples, samplerate, false);
387	      metadata.audioEncoding = "pcm";
388	    } else {
389	      metadata.audio = utils.encodeAudio(samples, samplerate, true);
390	      metadata.audioEncoding = "wav";
391	    }
392	
393	    // Sent the TalkingHead object to the original caller
394	    item.ref = item.id;
395	    delete item.id;
396	    item.type = "audio";
397	    item.data = metadata;
398	    eventHandler.postMessage(item, [metadata.audio]);
399	
400	  }
401	  isProcessing = false;
402	
403	}

