// https://huggingface.co/api/models/onnx-community/Kokoro-82M-v1.0-ONNX-timestamped (.sha).
const HF_REV = 'dd4401a9add81ac692d20e240d22ec9dda82cc29';
const HF_BASE = `https://huggingface.co/${HF_REPO}/resolve/${HF_REV}`;

