     3	export function createHighlighter({ reader, onSentence }) {
     4	  let raf = 0;
     5	  let getFrame = null;
     6	  let lastWordIdx = -1;
     7	  let lastSentence = -1;
     8	  let lastUserScrollAt = 0;
     9	  let programmaticUntil = 0;
    10	
    11	  const markUserScroll = () => {
    12	    if (performance.now() > programmaticUntil) lastUserScrollAt = performance.now();
    13	  };
    14	  window.addEventListener('wheel', markUserScroll, { passive: true });
    15	  window.addEventListener('touchmove', markUserScroll, { passive: true });
    16	
    17	  function tick() {
    18	    raf = requestAnimationFrame(tick);
    19	    const frame = getFrame?.();
    20	    if (!frame) return;
    21	    const { timeMs, words } = frame;
    22	    if (!words?.length) return;
    23	
    24	    const wi = lastWordAtOrBefore(words, timeMs);
    25	    if (wi === lastWordIdx) return;
    26	    lastWordIdx = wi;
    27	    if (wi < 0) return;
    28	
    29	    const si = reader.highlightWord(wi);
    30	    if (si >= 0 && si !== lastSentence) {
    31	      lastSentence = si;
    32	      reader.highlightSentence(si);
    33	      onSentence?.(si);
    34	      if (performance.now() - lastUserScrollAt > 3000) {
    35	        programmaticUntil = performance.now() + 1000;
    36	        reader.scrollToSentence(si);
    37	      }
    38	    }
    39	  }
    40	
    41	  function lastWordAtOrBefore(words, timeMs) {
    42	    let lo = 0;
    43	    let hi = words.length - 1;
    44	    let best = -1;
    45	    while (lo <= hi) {
    46	      const mid = (lo + hi) >> 1;
    47	      if (words[mid].startMs <= timeMs) {
    48	        best = mid;
    49	        lo = mid + 1;
    50	      } else {
    51	        hi = mid - 1;
    52	      }
    53	    }
    54	    return best;
    55	  }
    56	
    57	  return {
    58	    start(frameSource) {
    59	      getFrame = frameSource;
    60	      lastWordIdx = -1;
    61	      if (!raf) raf = requestAnimationFrame(tick);
    62	    },
    63	    stop() {
    64	      if (raf) cancelAnimationFrame(raf);
    65	      raf = 0;
    66	      getFrame = null;
    67	    },
    68	    resetWordState() {
    69	      lastWordIdx = -1;
    70	    },
    71	    noteSentence(si) {
    72	      lastSentence = si;
    73	    },
    74	    suppressAutoScroll(ms = 1000) {
    75	      programmaticUntil = performance.now() + ms;
    76	    },
    77	  };
    78	}
