function activateChunk(chunk, words) {
  deactivateChunk();
  ensureBlockSpans(chunk.block);
  activeChunk = chunk;
  wordEls = new Array(words.length).fill(null);
  wordSentence = new Array(words.length).fill(-1);

  const blockText = doc.blocks[chunk.block].text;
  const bySentence = new Map();
  let minStart = 0;
  words.forEach((w, wi) => {
    if (w.charStart < 0) return;
    const abs = chunk.start + w.charStart;
    if (abs < minStart) return; // tolerate out-of-order data
    for (let si = chunk.sentences[0]; si <= chunk.sentences[1]; si++) {
      const s = doc.sentences[si];
      if (abs >= s.start && abs < s.end) {
        if (!bySentence.has(si)) bySentence.set(si, []);
        bySentence.get(si).push(wi);
        wordSentence[wi] = si;
        minStart = Math.min(chunk.start + w.charEnd, s.end);
        break;
      }
    }
  });

  // words with no char match still need a sentence for highlight continuity:
  // inherit from the previous matched word (or the chunk's first sentence)
  let lastSeen = chunk.sentences[0];
  for (let wi = 0; wi < words.length; wi++) {
    if (wordSentence[wi] === -1) wordSentence[wi] = lastSeen;
    else lastSeen = wordSentence[wi];
  }

  for (const [si, wis] of bySentence) {
    const s = doc.sentences[si];
    const frag = document.createDocumentFragment();
    let cursor = s.start;
    for (const wi of wis) {
      const w = words[wi];
      const abs = chunk.start + w.charStart;
      const absEnd = Math.min(chunk.start + w.charEnd, s.end);
      if (abs < cursor || absEnd <= abs) continue;
      if (abs > cursor) frag.appendChild(document.createTextNode(blockText.slice(cursor, abs)));
      const wEl = document.createElement('span');
      wEl.className = 'w';
      wEl.textContent = blockText.slice(abs, absEnd);
      frag.appendChild(wEl);
      wordEls[wi] = wEl;
      cursor = absEnd;
    }
  reader.scrollToSentence(si);

  maybePreloadNext();
  updateUI();
}

function resolveOffset(words, chunk) {
  if (pendingTarget.sentence != null) {
    const s = doc.sentences[pendingTarget.sentence];
    const w = words.find((w) => w.charStart >= 0 && chunk.start + w.charStart >= s.start);
    return w ? w.startMs : 0;
  }
  return pendingTarget.offsetMs ?? 0;
}

function sentenceAtOffset(words, offsetMs, chunk) {
  let wi = -1;
  for (let i = 0; i < words.length; i++) {
    if (words[i].startMs <= offsetMs) wi = i;
    else break;
  }
  if (wi >= 0) {
    const w = words[wi];
    if (w.charStart >= 0) {
      const abs = chunk.start + w.charStart;
      for (let si = chunk.sentences[0]; si <= chunk.sentences[1]; si++) {
        const s = doc.sentences[si];
        if (abs >= s.start && abs < s.end) return si;
      }
    }
  }
  sentHl.clear();
  CSS.highlights.delete('lectern-word');
  CSS.highlights.delete('lectern-sentence');
}

function buildChunkWords(idx, words) {
  if (!live?.chunks) return;
  const chunk = live.chunks[idx];
  const block = live.blocks[chunk.block];
  const built = words.map((w) => {
    if (w.charStart < 0) return { ...w, range: null, sentence: -1 };
    const start = chunk.start + w.charStart;
    const range = core.rangeFor(block, start, chunk.start + w.charEnd);
    let sentence = -1;
    for (let si = chunk.sentences[0]; si <= chunk.sentences[1]; si++) {
      const s = live.sentences[si];
      if (start >= s.start && start < s.end) {
        sentence = si;
        break;
      }
    }
    return { ...w, range, sentence };
  });
  let lastSeen = chunk.sentences[0];
  for (const w of built) {
    if (w.sentence === -1) w.sentence = lastSeen;
    else lastSeen = w.sentence;
  }
  live.chunkWords.set(idx, built);
  for (const old of live.chunkWords.keys()) {
    if (Math.abs(old - idx) > 2) live.chunkWords.delete(old);
  }
}

function sentenceRange(si) {
  const s = live.sentences[si];
  return core.rangeFor(live.blocks[s.block], s.start, s.end);
}

function tick() {
  live.raf = requestAnimationFrame(tick);
  const sync = live?.sync;
  if (!sync) return;
  const words = live.chunkWords.get(sync.idx);
  if (!words?.length) return;
  const t = sync.ms + (sync.playing ? (performance.now() - sync.recvAt) * sync.rate : 0);

  let lo = 0;
  let hi = words.length - 1;
  let wi = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (words[mid].startMs <= t) {
      wi = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  if (wi === live.lastWordIdx || wi < 0) return;
  live.lastWordIdx = wi;

