  function fetchChunk(idx) {
    inFlight++;
    const entry = { status: 'fetching' };
    entries.set(idx, entry);
    api
      .tts(provider, voice, chunks[idx].text)
      .then(({ audioBase64, words }) => {
        if (disposed) return;
        const bytes = Uint8Array.from(atob(audioBase64), (c) => c.charCodeAt(0));
        entry.blobUrl = URL.createObjectURL(new Blob([bytes], { type: 'audio/mpeg' }));
        entry.words = words;
        entry.status = 'ready';
        onReady?.(idx, entry);
      })
      .catch((err) => {
        if (disposed) return;
        entry.status = 'failed';
        entry.error = err;
        onError?.(idx, err);
      })
      .finally(() => {
        inFlight--;
        pump();
      });
  }

  function evict() {
    const ready = [...entries.entries()].filter(([, e]) => e.status === 'ready');
    if (ready.length <= MAX_READY) return;
    ready
      .sort((a, b) => Math.abs(b[0] - focus) - Math.abs(a[0] - focus))
      .slice(0, ready.length - MAX_READY)
      .forEach(([idx, entry]) => {
        URL.revokeObjectURL(entry.blobUrl);
        entries.delete(idx);
      });
  }

  return {
    const next = cur + 1;
    if (next >= chunks.length || standbyIdx === next) return;
    const entry = queue.get(next);
    if (entry?.status === 'ready') preloadStandby(next, entry);
  }

  function preloadStandby(idx, entry) {
    standby.src = entry.blobUrl;
    standby.preload = 'auto';
    applyRate(standby);
    standby.load();
    standbyIdx = idx;
  }

  function onEnded(el) {
    if (el !== active || disposed) return;
    const next = cur + 1;
    if (next >= chunks.length) {
      wantPlay = false;
      savePosition(true);
      updateUI();
      return;
    }
    const entry = queue.get(next);
    if (standbyIdx === next && entry?.status === 'ready') {
      [active, standby] = [standby, active];
      standbyIdx = -1;
      cur = next;
      boundIdx = cur;
      reader.activateChunk(chunks[cur], entry.words);
      highlighter.resetWordState();
      if (!durations.has(cur) && active.duration) durations.set(cur, active.duration * 1000);
      applyRate(active);
      if (wantPlay) active.play().catch(reportPlayFailure);
      queue.ensureWindow(cur);
      maybePreloadNext();
      updateUI();
    } else {
      loadChunk(next);
    }
  }

  audioA.addEventListener('ended', () => onEnded(audioA));
  audioB.addEventListener('ended', () => onEnded(audioB));

  function reportPlayFailure(err) {
    wantPlay = false;
    updateUI();
    onError?.(new Error(`Playback blocked: ${err.message}`));
  }

