const rhe = (x) => { const f = Math.floor(x); const r = x - f; return r > 0.5 ? f + 1 : r < 0.5 ? f : (f % 2 === 0 ? f : f + 1); };
const check = async (txt, speed = 1) => {
  const { phonemes } = lang.generate(txt);
  const ids2 = [];
  for (const p of phonemes) for (const ch of p) { const id = vocab.get(ch); if (id !== undefined) ids2.push(id); }
  const st = table.slice(Math.min(ids2.length, 509) * 256, Math.min(ids2.length, 509) * 256 + 256);
  const o = await sess.run({
    input_ids: new ort.Tensor('int64', BigInt64Array.from([0, ...ids2, 0].map(BigInt)), [1, ids2.length + 2]),
    style: new ort.Tensor('float32', st, [1, 256]),
    speed: new ort.Tensor('float32', Float32Array.from([speed]), [1]),
  });
  const d = Array.from(o.durations.data);
  const rounded = d.map((x) => Math.max(1, rhe(x)));
  const rsum = rounded.reduce((a, b) => a + b, 0);
  const fsum = d.reduce((a, b) => a + b, 0);
  console.log(`n=${ids2.length} samples=${o.waveform.data.length} roundedFrames*600=${rsum * 600} floatFrames*600=${Math.round(fsum * 600)} exact=${rsum * 600 === o.waveform.data.length}`);
};
