    // (token 6) and ends before the period (token 13)
    expect(words).toEqual([
      { text: 'Hello', startMs: frameMs(4), endMs: frameMs(14), charStart: 0, charEnd: 5 },
      { text: 'world', startMs: frameMs(18), endMs: frameMs(30), charStart: 7, charEnd: 12 },
    ]);
  });

