    const res = await kokoro.synthesize({ text: '日本語', voice: 'af_heart' });
    expect(fakeOrt.run).not.toHaveBeenCalled();
    expect(looksLikeMp3(res.audio)).toBe(true);
    expect(res).toMatchObject({ format: 'mp3', words: [] });
  });

