process.env.KOKORO_DIR ??= '/Users/hungpq2412/lectern/data/kokoro';
const kokoro = await import('../wt-kokoro/server/providers/kokoro.js');
const decodeMs = (mp3) => execFileSync('ffmpeg', ['-v', 'quiet', '-f', 'mp3', '-i', 'pipe:0', '-f', 'f32le', '-ac', '1', '-ar', '24000', 'pipe:1'], { input: mp3, maxBuffer: 256 * 1024 * 1024 }).byteLength / 4 / 24;
const long = 'In the long and winding history of the craft, which stretched across many countries, languages and generations of patient workers who rarely signed their names, ' +
  'the small improvements in ink, in paper, in type metal and in the presses themselves accumulated slowly, one after another, until the cost of a book fell far enough ' +
  'that ordinary families could own several of them, and the habit of private reading, once the privilege of monks, merchants and princes, spread through towns and villages ' +
  'in a way that nobody at the start could have predicted, and that changed how people argued, prayed, worked, voted and understood themselves and the world around them, ' +
  'while printers, booksellers, translators and censors all adapted, sometimes eagerly and sometimes grudgingly, to a market that kept growing faster than any of them expected';
const cases = {
  punctOnly: '...',
  dash: '—',
  emoji: 'Great work 🎉 everyone!',
  bigNumber: 'The total was 123456789012345678901234567890 dollars.',
  sci: 'Values like 1e10 and 3.14159 and -0.5 appear.',
  mixed: 'Café, naïve résumé; “quoted” text — and (parentheses) [brackets] {braces}.',
  curly: 'I’ll say it’s the users’ choice, isn’t it?',
  url: 'Visit https://example.com/some/path?query=1&x=2 for details.',
  newline: 'First line.\nSecond line after a newline.',
  longSentence: long,
};
for (const [name, text] of Object.entries(cases)) {
  const t0 = performance.now();
  const { audio, words } = await kokoro.synthesize({ text, voice: 'am_michael' });
  const ms = decodeMs(audio);
  const bad = [];
  words.forEach((w, i) => {
    if (w.charStart >= 0 && text.slice(w.charStart, w.charEnd) !== w.text) bad.push(`slice ${i}`);
    if (!(w.endMs >= w.startMs)) bad.push(`order ${i}`);
    if (i && w.startMs < words[i - 1].startMs) bad.push(`mono ${i}`);
    if (w.endMs > ms + 1) bad.push(`past-end ${i}`);
    if (!Number.isFinite(w.startMs)) bad.push(`nan ${i}`);
  });
  const segWords = [...new Intl.Segmenter('en', { granularity: 'word' }).segment(text)].filter((s) => s.isWordLike).length;
  console.log(`${name.padEnd(12)} chars=${String(text.length).padStart(4)} words=${words.length}/${segWords} audio=${Math.round(ms)}ms wall=${Math.round(performance.now() - t0)}ms ${bad.length ? 'BAD ' + bad.slice(0, 5).join(',') : 'ok'}${name === 'longSentence' ? ` lastEnd=${words.at(-1).endMs}` : ''}`);
}
EOF
